public String toString() {String biffName = getBiffName(_sid);if (biffName == null) {biffName = "UNKNOWNRECORD";}StringBuilder sb = new StringBuilder();sb.append('[').append(biffName).append("] (0x");sb.append(Integer.toHexString(_sid).toUpperCase(Locale.ROOT)).append(")
");if (_rawData.length > 0) {sb.append("  rawData=").append(HexDump.toHex(_rawData)).append("
");}sb.append("[/").append(biffName).append("]
");return sb.toString();}

