public override String ToString(){String biffName = GetBiffName(_sid);if (biffName == null){biffName = "UNKNOWNRECORD";}StringBuilder sb = new StringBuilder();sb.Append("[").Append(biffName).Append("] (0x");sb.Append(StringUtil.ToHexString(_sid).ToUpper() + ")
");if (_rawData.Length > 0){sb.Append("  rawData=").Append(HexDump.ToHex(_rawData)).Append("
");}sb.Append("[/").Append(biffName).Append("]
");return sb.ToString();}

